create extension if not exists pgcrypto;
create table public.admin_users(user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz not null default now());
create table public.categories(id uuid primary key default gen_random_uuid(),name text not null unique check(char_length(name) between 2 and 80),slug text not null unique,active boolean not null default true,sort_order integer not null default 0 check(sort_order>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.products(id uuid primary key default gen_random_uuid(),name text not null check(char_length(name) between 2 and 120),slug text not null unique,description text not null default '',price numeric(12,2) not null check(price>=0),category_id uuid not null references public.categories(id) on delete restrict,published boolean not null default false,available boolean not null default true,featured boolean not null default false,is_new boolean not null default false,customizable boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.product_images(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,storage_path text not null unique,sort_order integer not null default 0 check(sort_order>=0),created_at timestamptz not null default now());
create index products_public_idx on public.products(published,available,created_at desc);create index products_category_idx on public.products(category_id);create index product_images_product_idx on public.product_images(product_id,sort_order);create index categories_order_idx on public.categories(active,sort_order);
create function public.set_updated_at() returns trigger language plpgsql security invoker set search_path='' as $$ begin new.updated_at=now();return new;end $$;
create trigger categories_updated before update on public.categories for each row execute function public.set_updated_at();create trigger products_updated before update on public.products for each row execute function public.set_updated_at();
create function public.is_admin() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.admin_users where user_id=auth.uid())$$;
revoke all on function public.is_admin() from public;grant execute on function public.is_admin() to anon,authenticated;
alter table public.admin_users enable row level security;alter table public.categories enable row level security;alter table public.products enable row level security;alter table public.product_images enable row level security;
create policy "admin reads own authorization" on public.admin_users for select to authenticated using(user_id=auth.uid());
create policy "public reads active categories" on public.categories for select to anon,authenticated using(active or public.is_admin());
create policy "admins manage categories" on public.categories for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "public reads published products" on public.products for select to anon,authenticated using(published or public.is_admin());
create policy "admins manage products" on public.products for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "public reads published product images" on public.product_images for select to anon,authenticated using(exists(select 1 from public.products p where p.id=product_id and (p.published or public.is_admin())));
create policy "admins manage product images" on public.product_images for all to authenticated using(public.is_admin()) with check(public.is_admin());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('product-images','product-images',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=true,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy "public views product images" on storage.objects for select to public using(bucket_id='product-images');
create policy "admins upload product images" on storage.objects for insert to authenticated with check(bucket_id='product-images' and public.is_admin());
create policy "admins update product images" on storage.objects for update to authenticated using(bucket_id='product-images' and public.is_admin()) with check(bucket_id='product-images' and public.is_admin());
create policy "admins delete product images" on storage.objects for delete to authenticated using(bucket_id='product-images' and public.is_admin());
insert into public.categories(name,slug,sort_order) values('Presentes personalizados','presentes-personalizados',1),('Kits especiais','kits-especiais',2),('Canecas','canecas',3),('Pelúcias','pelucias',4),('Presentes românticos','presentes-romanticos',5),('Datas comemorativas','datas-comemorativas',6),('Outros mimos','outros-mimos',7) on conflict(slug) do nothing;
